ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS geographic_level text NOT NULL DEFAULT 'county';
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS assigned_county text NOT NULL DEFAULT 'Makueni';
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS assigned_constituencies jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS assigned_wards jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS assigned_polling_centres jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS assigned_polling_stations jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS assigned_villages jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE TABLE IF NOT EXISTS approval_requests (id serial PRIMARY KEY,token text UNIQUE NOT NULL,module text NOT NULL,action text NOT NULL,resource_type text NOT NULL,resource_id text,title text NOT NULL,description text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'pending',requested_by_id integer NOT NULL,requested_by_email text NOT NULL,reviewed_by_id integer,reviewed_by_email text,review_comment text,expires_at timestamp NOT NULL,reviewed_at timestamp,executed_at timestamp,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approval_events (id serial PRIMARY KEY,request_id integer NOT NULL,event text NOT NULL,actor_id integer NOT NULL,actor_email text NOT NULL,comment text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contact_import_batches (id serial PRIMARY KEY,filename text NOT NULL,status text NOT NULL DEFAULT 'processing',imported_by_id integer NOT NULL,total_rows integer NOT NULL DEFAULT 0,accepted_rows integer NOT NULL DEFAULT 0,duplicate_rows integer NOT NULL DEFAULT 0,invalid_rows integer NOT NULL DEFAULT 0,error_report jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamp NOT NULL DEFAULT now(),completed_at timestamp);
CREATE TABLE IF NOT EXISTS campaign_contacts (id serial PRIMARY KEY,full_name text NOT NULL,normalized_phone text NOT NULL UNIQUE,original_phone text,email text,county text NOT NULL DEFAULT 'Makueni',constituency text,ward text,polling_centre text,polling_station text,village text,source text NOT NULL DEFAULT 'import',consent_status text NOT NULL DEFAULT 'unknown',import_batch_id integer,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,is_active boolean NOT NULL DEFAULT true,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS approval_requests_status_idx ON approval_requests(status);
CREATE INDEX IF NOT EXISTS campaign_contacts_ward_idx ON campaign_contacts(ward);
